#!/usr/bin/env bash
# Every check a commit must pass before it ships. CI and the pre-push hooks run
# this same script, so passing locally means passing in CI.
set -euo pipefail
cd "$(dirname "$0")/.."

echo '==> format'
# firebase_options.dart is generated by flutterfire, so it's left as generated.
find lib test integration_test tool -name '*.dart' ! -name firebase_options.dart -print0 \
  | xargs -0 dart format --output=none --set-exit-if-changed

echo '==> analyze'
flutter analyze --fatal-infos

echo '==> test'
flutter test --coverage

echo '==> size limits'
dart tool/size_check.dart

echo '==> comments'
./scripts/test-comment-check.sh
./scripts/comment-check.sh

echo '==> tests changed with lib/'
./scripts/test-tests-changed.sh
./scripts/tests-changed.sh

echo '==> coverage'
./scripts/test-coverage.sh
./scripts/coverage.sh

echo '==> hooks, reviewer mapping and review gate'
./scripts/test-hooks.sh
./scripts/test-required-reviewers.sh
./scripts/test-review-gate.sh

echo '==> firestore rules'
[ -d firestore-tests/node_modules ] || npm --prefix firestore-tests ci --no-fund --no-audit
npm --prefix firestore-tests test
